"""Keep vulnerability coverage separate from other scanner successes."""
import json


def coverage_outcome(report_json):
    report = json.loads(report_json)
    results = report["scanners"]
    age = report.get("advisory_age_hours")
    database_fresh = type(age) is int and 0 <= age <= 24
    required = ("vulnerability", "misconfiguration", "secret")
    missing = [name for name in required if results.get(name) != "completed"]
    if not database_fresh or missing:
        return {"status": "incomplete", "clean": False}
    findings = report.get("findings", [])
    return {"status": "completed", "clean": not findings}

